import React, { useState } from "react";
import axios from "axios";
import "../styles/Upload.css";
// 1. Import the high-tech icons
import { HiOutlineSearchCircle } from "react-icons/hi"; 
import { RiDeleteBin6Line } from "react-icons/ri";

const Upload = () => {
  const [image, setImage] = useState(null);
  const [preview, setPreview] = useState(null);
  const [resultImage, setResultImage] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleImageChange = (file) => {
    if (file) {
      setImage(file);
      setPreview(URL.createObjectURL(file));
    } else {
      console.log("No file selected");
    }
  };

  function handleDrop(e) {
    e.preventDefault();
    const file = e.dataTransfer.files[0];
    handleImageChange(file);
  }

  const handleDragOver = (e) => {
    e.preventDefault();
  };

  const handleDetect = async () => {
    if (!image) {
      alert("Please upload an image first!");
      return;
    }
    const formData = new FormData();
    formData.append("image", image);
    try {
      setLoading(true);
      const response = await axios.post(
        "http://127.0.0.1:5000/detect",
        formData,
        { headers: { "Content-Type": "multipart/form-data" } }
      );
      setResultImage(`${response.data.result_image}?t=${new Date().getTime()}`);
      setLoading(false);
    } catch (error) {
      console.error(error);
      alert("Detection failed!");
      setLoading(false);
    }
  };

  const handleClear = () => {
    setImage(null);
    setPreview(null);
    setResultImage(null);
  };

  return (
    <div className="upload-container">
      <h2>📤 Upload Image</h2>
      <p>Analyze marine environments for plastic and debris.</p>

      <div
        className="drop-area"
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onClick={() => document.getElementById("fileInput").click()}
      >
        {preview ? (
          <img src={preview} alt="Preview" className="preview-img" />
        ) : (
          <p>Drag & Drop or Click to Upload</p>
        )}
      </div>

      <input
        type="file"
        id="fileInput"
        hidden
        accept="image/*"
        onChange={(e) => handleImageChange(e.target.files[0])}
      />

      <div className="button-group">
        <button className="glass-btn detect-btn" onClick={handleDetect} disabled={loading}>
          {loading ? (
            "Processing..."
          ) : (
            <>
              <HiOutlineSearchCircle className="btn-icon pulse" /> Detect Objects
            </>
          )}
        </button>

        <button className="glass-btn clear-btn" onClick={handleClear}>
          <RiDeleteBin6Line className="btn-icon" /> Clear Workspace
        </button>
      </div>

      {resultImage && (
        <div className="result-section">
          <h3>✅ Analysis Complete</h3>
          <img src={resultImage} alt="Result" className="result-img" />
        </div>
      )}
    </div>
  );
};

export default Upload;
